function postfixLedger(tokens) {
  const items = tokens.map((t) => (['+', '-', '*', '/'].includes(t) ? t : Number(t)));
  while (items.length > 1) {
    const i = items.findIndex((t) => typeof t === 'string');
    const a = items[i - 2], b = items[i - 1], op = items[i];
    const value = op === '+' ? a + b : op === '-' ? a - b : op === '*' ? a * b : Math.trunc(a / b);
    items.splice(i - 2, 3, value);
  }
  return items[0];
}

